import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.ChTAMbUy.js";const c=JSON.parse('{"title":"Platform Settings","description":"","frontmatter":{},"headers":[],"relativePath":"1.10/admin/platform_settings.md","filePath":"versions/1.10/admin/platform_settings.md","lastUpdated":1795112498000}'),n={name:"1.10/admin/platform_settings.md"};function r(i,e,l,d,g,h){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="platform-settings" tabindex="-1">Platform Settings <a class="header-anchor" href="#platform-settings" aria-label="Permalink to &quot;Platform Settings&quot;">​</a></h1><p>Use <strong>Admin &gt; Platform Settings</strong> to change the portal&#39;s branding and choose which features appear in the prokube portal. The settings apply to all users and workspaces. Access requires the Keycloak <code>realm-admin</code> role.</p><h2 id="change-branding" tabindex="-1">Change Branding <a class="header-anchor" href="#change-branding" aria-label="Permalink to &quot;Change Branding&quot;">​</a></h2><p>Under <strong>Deployment branding</strong>, set the <strong>Display name</strong> and <strong>Tagline</strong> shown next to the logo. An empty display name uses the value from the deployment configuration; an empty tagline hides the tagline. <strong>Brand preview</strong> shows the result before you save.</p><p>To replace the logo, select a JPEG, PNG, or WebP file of up to 512 KB and at most 2,048 px per side, then select <strong>Upload logo</strong>. A square image works best; use PNG or WebP for transparency. The logo applies as soon as it is uploaded; <strong>Remove uploaded logo</strong> restores the deployment default.</p><h2 id="choose-visible-features" tabindex="-1">Choose Visible Features <a class="header-anchor" href="#choose-visible-features" aria-label="Permalink to &quot;Choose Visible Features&quot;">​</a></h2><p>Under <strong>Shown in portal</strong>, switch individual features on or off, or use the <strong>MLOps</strong> and <strong>AgentOps</strong> suite controls to switch a whole group. Only features installed in the deployment are listed.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/platform-settings-shown-in-portal-framed.png" alt="Shown in portal settings with MLOps and AgentOps suite controls and individual feature switches" loading="lazy"></p><table tabindex="0"><thead><tr><th>Suite</th><th>Features</th></tr></thead><tbody><tr><td>MLOps</td><td>Labs, Hparam Search, MLflow, Pipelines, Volumes</td></tr><tr><td>AgentOps</td><td>LLM Serving, MCP Servers, Agents, Memory, Sandboxes</td></tr><tr><td>Both</td><td>Models, Serverless, API Keys, Object Storage, External Models, LLM Usage and Cost</td></tr></tbody></table><p>The <strong>API Keys</strong> switch also controls <strong>Gateway Usage</strong> under <strong>Monitoring</strong>.</p><p>Features in both suites stay visible while either suite is on. For example, turning off <strong>AgentOps</strong> hides Agents and Memory, but Models and API Keys stay visible because <strong>MLOps</strong> is still on. When both suites are off, these shared features are hidden and can&#39;t be switched on individually.</p><p>A suite control is shown as mixed when only some of its features are visible. Selecting it shows all of them again.</p><p><strong>Logs</strong>, <strong>User Management</strong>, <strong>Platform Settings</strong>, and <strong>System Status</strong> can&#39;t be hidden.</p><h2 id="save-changes" tabindex="-1">Save Changes <a class="header-anchor" href="#save-changes" aria-label="Permalink to &quot;Save Changes&quot;">​</a></h2><p>Changes to the display name, tagline, and visible features take effect only after you select <strong>Save settings</strong>. Your portal updates right away, without a redeploy; other users see the change after reloading. If the page shows <strong>Settings saved; refresh needed</strong>, reload it.</p><p>If another administrator saved in the meantime, select <strong>Review latest changes</strong>, compare their version with your draft, and save again.</p><h2 id="what-hiding-does" tabindex="-1">What Hiding Does <a class="header-anchor" href="#what-hiding-does" aria-label="Permalink to &quot;What Hiding Does&quot;">​</a></h2><p>Hiding a feature removes it from navigation, and its pages show as unavailable. Hiding doesn&#39;t uninstall components, disable backend APIs, or change permissions, so users can still reach a hidden feature through its API. To restrict access, use RBAC or the deployment configuration.</p><p>Hiding <strong>MLflow</strong> also removes <strong>Import from MLflow</strong> from the <strong>Models</strong> create flow.</p><div class="warning custom-block"><p class="custom-block-title">Reset also clears branding</p><p><strong>Reset to deployment defaults</strong> shows all features again, but also removes custom branding and the uploaded logo.</p></div><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./user_management.html">User Management</a></li><li><a href="./../platform/system_status.html">System Status</a></li></ul>',22)])])}const u=t(n,[["render",r]]);export{c as __pageData,u as default};
